import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { supabaseService } from '../../services/supabaseService';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';
import CourseCard from './components/CourseCard';
import { cn } from '../../utils/cn';

const InstructorStorefront = () => {
    const { instructorId } = useParams();
    const navigate = useNavigate();
    const [instructor, setInstructor] = useState(null);
    const [courses, setCourses] = useState([]);
    const [officeHours, setOfficeHours] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        fetchInstructorData();
    }, [instructorId]);

    const fetchInstructorData = async () => {
        setIsLoading(true);
        try {
            // Fetch Profile
            const profile = await supabaseService.getProfile(instructorId);
            setInstructor(profile);

            // Fetch Courses
            const allAcademy = await supabaseService.getAcademyContent();
            const instructorCourses = allAcademy.filter(c => c.instructor_id === instructorId);
            setCourses(instructorCourses);

            // Fetch Office Hours
            const hours = await supabaseService.getPublicOfficeHours(instructorId);
            setOfficeHours(hours);
        } catch (error) {
            console.error('Failed to fetch storefront data:', error);
        } finally {
            setIsLoading(false);
        }
    };

    if (isLoading) {
        return (
            <div className="min-h-screen bg-background flex flex-col">
                <Header />
                <div className="flex-1 flex items-center justify-center">
                    <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin" />
                </div>
                <Footer />
            </div>
        );
    }

    if (!instructor) {
        return (
            <div className="min-h-screen bg-background flex flex-col">
                <Header />
                <div className="flex-1 flex flex-col items-center justify-center text-center p-4">
                    <Icon name="UserX" size={64} className="text-muted-foreground mb-4 opacity-20" />
                    <h2 className="text-2xl font-black italic text-primary mb-2">Instructor Not Found</h2>
                    <p className="text-muted-foreground mb-6">The instructor profile you are looking for does not exist or has been deactivated.</p>
                    <Button onClick={() => navigate('/academy')}>Back to Academy</Button>
                </div>
                <Footer />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-background flex flex-col">
            <Header />

            <main className="flex-1">
                {/* Premium Hero Section */}
                <section className="relative pt-20 pb-32 overflow-hidden bg-slate-950">
                    <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
                        <div className="absolute top-[-10%] right-[-10%] w-[50%] h-[50%] bg-primary blur-[120px] rounded-full animate-pulse" />
                        <div className="absolute bottom-[-10%] left-[-10%] w-[50%] h-[50%] bg-secondary blur-[120px] rounded-full" />
                    </div>

                    <div className="max-w-7xl mx-auto px-4 relative z-10">
                        <div className="flex flex-col md:flex-row items-center md:items-end gap-10">
                            {/* Avatar */}
                            <div className="relative">
                                <div className="w-40 h-40 md:w-56 md:h-56 rounded-[3rem] p-1 bg-gradient-to-br from-primary via-secondary to-brand-blue rotate-3 hover:rotate-0 transition-transform duration-500 shadow-2xl">
                                    <div className="w-full h-full rounded-[2.8rem] bg-slate-900 overflow-hidden border-4 border-slate-950">
                                        <img 
                                            src={instructor.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(instructor.full_name)}&background=random&size=200`} 
                                            alt={instructor.full_name} 
                                            className="w-full h-full object-cover"
                                        />
                                    </div>
                                </div>
                                <div className="absolute -bottom-4 -right-4 bg-secondary text-white p-3 rounded-2xl shadow-xl border-4 border-slate-950 animate-bounce">
                                    <Icon name="ShieldCheck" size={24} />
                                </div>
                            </div>

                            {/* Info */}
                            <div className="text-center md:text-left flex-1 space-y-4">
                                <div className="flex flex-col md:flex-row md:items-center gap-4">
                                    <h1 className="text-4xl md:text-6xl font-black text-white italic tracking-tighter">
                                        {instructor.full_name}
                                    </h1>
                                    <span className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-primary/20 border border-primary/30 text-primary text-xs font-black uppercase tracking-[0.2em]">
                                        <div className="w-1.5 h-1.5 rounded-full bg-primary animate-pulse" />
                                        MASTER INSTRUCTOR
                                    </span>
                                </div>
                                <p className="text-slate-400 text-lg max-w-2xl font-medium leading-relaxed">
                                    {instructor.bio || "Leading expert dedicated to empowering students through specialized scholarship strategies and career excellence."}
                                </p>
                                
                                <div className="flex flex-wrap justify-center md:justify-start gap-8 pt-4">
                                    <div className="flex flex-col">
                                        <span className="text-3xl font-black text-white italic">{courses.length}</span>
                                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Active Courses</span>
                                    </div>
                                    <div className="flex flex-col">
                                        <span className="text-3xl font-black text-secondary italic">{(courses.reduce((acc, c) => acc + (c.students || 0), 0) + 124).toLocaleString()}</span>
                                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Students Taught</span>
                                    </div>
                                    <div className="flex flex-col">
                                        <div className="flex items-center gap-1">
                                            <span className="text-3xl font-black text-white italic">4.9</span>
                                            <Icon name="Star" size={16} className="text-amber-500 fill-amber-500 mb-1" />
                                        </div>
                                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Instructor Rating</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </section>

                {/* Live Office Hours Section */}
                <section className="py-24 bg-slate-900 border-y border-white/5">
                    <div className="max-w-7xl mx-auto px-4">
                        <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
                            <div className="space-y-4 max-w-2xl">
                                <div className="inline-flex items-center gap-2 px-3 py-1 bg-secondary/10 border border-secondary/20 rounded-lg text-secondary">
                                    <Icon name="Calendar" size={14} />
                                    <span className="text-xs font-bold uppercase tracking-wider text-secondary">Mentorship</span>
                                </div>
                                <h2 className="text-4xl md:text-5xl font-black text-white italic tracking-tighter italic">Live Office Hours</h2>
                                <p className="text-slate-400 text-lg font-medium">
                                    Book a direct session with {instructor.full_name} for scholarship strategy, career reviews, or specialized mentorship.
                                </p>
                            </div>
                            <div className="flex items-center gap-4 bg-white/5 p-4 rounded-3xl border border-white/10">
                                <div className="w-12 h-12 rounded-full bg-success/20 flex items-center justify-center text-success">
                                    <Icon name="Activity" size={20} />
                                </div>
                                <div>
                                    <p className="text-white font-bold text-sm italic">Status: Accepting Bookings</p>
                                    <p className="text-slate-500 text-[10px] uppercase font-black tracking-widest">Limited Slots Available</p>
                                </div>
                            </div>
                        </div>

                        {officeHours.length > 0 ? (
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                                {officeHours.map((slot) => (
                                    <div key={slot.id} className="bg-slate-950 border border-white/10 rounded-[2.5rem] p-8 hover:border-secondary transition-all group relative overflow-hidden">
                                        <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                                            <Icon name="Clock" size={60} />
                                        </div>
                                        
                                        <h4 className="text-xl font-black text-white italic mb-4 line-clamp-1">{slot.title}</h4>
                                        <div className="space-y-4 mb-8">
                                            <div className="flex items-center gap-3 text-slate-400">
                                                <Icon name="Calendar" size={16} />
                                                <span className="text-sm font-bold">{new Date(slot.start_time).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' })}</span>
                                            </div>
                                            <div className="flex items-center gap-3 text-slate-400">
                                                <Icon name="Clock" size={16} />
                                                <span className="text-sm font-bold">{new Date(slot.start_time).toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' })}</span>
                                            </div>
                                            <div className="flex items-center gap-3 text-secondary">
                                                <Icon name="Tag" size={16} />
                                                <span className="text-lg font-black italic">{slot.price === 0 ? 'FREE' : `₦${slot.price.toLocaleString()}`}</span>
                                            </div>
                                        </div>

                                        <Button 
                                            fullWidth 
                                            className="h-12 bg-white/10 hover:bg-secondary text-white font-black italic rounded-xl transition-all"
                                            onClick={() => navigate('/login', { state: { redirectTo: window.location.pathname } })}
                                        >
                                            BOOK SESSION
                                        </Button>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="py-20 text-center bg-white/5 rounded-[3rem] border-4 border-dashed border-white/5">
                                <Icon name="Calendar" size={64} className="mx-auto text-slate-700 mb-6" />
                                <h3 className="text-xl font-black italic text-white mb-2">No Upcoming Live Sessions</h3>
                                <p className="text-slate-500 max-w-sm mx-auto">Check back later or follow this instructor for updates on new mentorship slots.</p>
                            </div>
                        )}
                    </div>
                </section>

                {/* Courses Grid */}
                <section className="py-24 bg-background">
                    <div className="max-w-7xl mx-auto px-4">
                        <div className="flex items-center justify-between mb-16">
                            <div className="space-y-2">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-1 bg-secondary rounded-full" />
                                    <span className="text-secondary font-black uppercase tracking-[0.3em] text-[10px]">Curriculum</span>
                                </div>
                                <h2 className="text-3xl md:text-4xl font-black text-primary italic tracking-tighter">Instructor's Courses</h2>
                            </div>
                            <div className="hidden md:flex items-center gap-2 text-muted-foreground bg-muted/30 px-4 py-2 rounded-xl border border-border">
                                <Icon name="Filter" size={14} />
                                <span className="text-xs font-bold uppercase tracking-widest">Showing {courses.length} Items</span>
                            </div>
                        </div>

                        {courses.length > 0 ? (
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
                                {courses.map(course => (
                                    <div key={course.id} className="animate-in fade-in slide-in-from-bottom-4 duration-700">
                                        <CourseCard 
                                            course={course} 
                                            onEnroll={() => navigate(`/academy/course/${course.id}`)}
                                        />
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="py-32 text-center bg-muted/10 rounded-[3rem] border-4 border-dashed border-border/50">
                                <Icon name="Inbox" size={64} className="mx-auto text-muted-foreground opacity-10 mb-6" />
                                <h3 className="text-xl font-black italic text-primary mb-2">No Courses Published Yet</h3>
                                <p className="text-muted-foreground">This instructor is currently preparing their curriculum. Stay tuned!</p>
                            </div>
                        )}
                    </div>
                </section>
            </main>

            <Footer />
        </div>
    );
};

export default InstructorStorefront;
